    // No emoji anywhere in the chrome this feature added (Final Directive).
    const EMOJI = /[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}]/u;
    assert(!EMOJI.test(nav.textContent), 'the Clan nav entry contains emoji');
