      // Meeting the requirement works.
      G.wieldGrandfather = {}; G.inventory = { [rid]: 1 }; G.equipment = {}; G.skills = { defense: 5000000 };
      window.equipItem(rid);
      assert(isEquipped(), 'meeting the requirement lets you equip');
