      if (!wasOn) A.setServerAccrualEnabled(false);   // b353: pristine (=ON) first, then re-apply OFF only if we started there
      M.resetActivity(); M.configureActivity(null);
      try { window.stopCombat(); } catch (e) {}
      Object.assign(G, save);
